:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
  background: rgba(20, 23, 31, 0.6);
  backdrop-filter: blur(8px);
}

.brand {
  font-weight: 700;
  letter-spacing: 0.02em;
  font-size: 1.05rem;
  color: var(--text);
}

.nav-list {
  display: flex;
  gap: 0.25rem;
  margin: 0;
  padding: 0;
  list-style: none;
}
.nav-list a {
  display: inline-block;
  padding: 0.5rem 0.85rem;
  color: var(--text-muted);
  text-decoration: none;
  border-radius: 6px;
  font-size: 0.95rem;
}
.nav-list a:hover { color: var(--text); background: var(--surface-2); }
.nav-list a[aria-current="page"] {
  color: var(--text);
  background: var(--surface-2);
}

.preview {
  max-width: 880px;
  margin: 0 auto;
  padding: 2rem 1.25rem 4rem;
}

.preview-title {
  margin: 0 0 0.25rem;
  font-size: clamp(1.5rem, 2.5vw, 2rem);
  font-weight: 700;
  letter-spacing: -0.01em;
}

.preview-meta {
  margin: 0 0 1.5rem;
  color: var(--text-muted);
  font-size: 0.95rem;
}

.preview-figure {
  margin: 0 0 1.25rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: var(--shadow);
}

.preview-image {
  display: block;
  width: 100%;
  aspect-ratio: 8 / 5;
  background: #0b1733;
}
.preview-image svg { width: 100%; height: 100%; display: block; }

.preview-caption {
  padding: 0.85rem 1.1rem;
  color: var(--text-muted);
  font-size: 0.92rem;
  border-top: 1px solid var(--border);
}

.preview-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
  margin-top: 0.5rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.65rem 1.1rem;
  min-height: 44px;
  font: inherit;
  font-weight: 600;
  font-size: 0.95rem;
  border-radius: 8px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, transform 0.05s ease;
}
.btn:active { transform: translateY(1px); }

.btn-secondary {
  background: var(--surface-2);
  color: var(--text);
  border-color: var(--border-strong);
}
.btn-secondary:hover { background: #242935; }

.btn-danger {
  background: var(--danger);
  color: #1a0408;
  border-color: var(--danger);
}
.btn-danger:hover { background: var(--danger-strong); border-color: var(--danger-strong); }

.status {
  margin-top: 1rem;
  min-height: 1.5em;
  color: var(--text-muted);
  font-size: 0.95rem;
}

/* Modal dialog */
.modal {
  padding: 0;
  border: 1px solid var(--border-strong);
  border-radius: 14px;
  background: var(--surface);
  color: var(--text);
  width: min(440px, calc(100vw - 2rem));
  max-width: 440px;
  box-shadow: var(--shadow);
}
.modal::backdrop {
  background: rgba(5, 7, 12, 0.7);
  backdrop-filter: blur(4px);
}

.modal-inner {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.modal-title {
  margin: 0;
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: -0.005em;
}

.modal-body {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.97rem;
}
.modal-body strong { color: var(--text); font-weight: 600; }

.modal-actions {
  display: flex;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-top: 0.25rem;
}

@media (max-width: 380px) {
  .modal-actions { flex-direction: column-reverse; align-items: stretch; }
  .modal-actions .btn { width: 100%; justify-content: center; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; }
}

@media (forced-colors: active) {
  .btn { border: 1px solid ButtonBorder; }
  .btn-danger { background: ButtonFace; color: ButtonText; }
  .modal { border: 1px solid CanvasText; }
}
