const fs = require('fs');
const path = require('path');
const puppeteer = require('puppeteer');
const { AxePuppeteer } = require('@axe-core/puppeteer');

const root = __dirname;
const types = { '.html': 'text/html', '.css': 'text/css', '.js': 'application/javascript' };

const server = http.createServer((req, res) => {
  let p = req.url === '/' ? '/index.html' : req.url;
  const fp = path.join(root, p);
  if (!fp.startsWith(root) || !fs.existsSync(fp)) { res.writeHead(404); res.end(); return; }
  res.writeHead(200, { 'Content-Type': types[path.extname(fp)] || 'text/plain' });
  res.end(fs.readFileSync(fp));
});

(async () => {
  await new Promise(r => server.listen(0, r));
  const port = server.address().port;
  const browser = await puppeteer.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage();
  await page.goto(`http://localhost:${port}/index.html`, { waitUntil: 'networkidle0' });

  const closed = await new AxePuppeteer(page).analyze();
  console.log('--- Closed state ---');
  console.log('Violations:', closed.violations.length);
  for (const v of closed.violations) {
    console.log(`[${v.impact}] ${v.id}: ${v.help}`);
    v.nodes.forEach(n => console.log('   ', n.target, '\n     ', n.failureSummary));
  }

  await page.click('.trigger');
  await new Promise(r => setTimeout(r, 200));

  const open = await new AxePuppeteer(page).analyze();
  console.log('--- Open state ---');
  console.log('Violations:', open.violations.length);
  for (const v of open.violations) {
    console.log(`[${v.impact}] ${v.id}: ${v.help}`);
    v.nodes.forEach(n => console.log('   ', n.target, '\n     ', n.failureSummary));
  }

  await browser.close();
  server.close();
  process.exit(closed.violations.length + open.violations.length > 0 ? 1 : 0);
})();
