const { AxePuppeteer } = require('@axe-core/puppeteer');

const root = __dirname;
const types = { '.html': 'text/html', '.css': 'text/css', '.js': 'application/javascript' };

const server = http.createServer((req, res) => {
  let p = req.url === '/' ? '/index.html' : req.url;
  const fp = path.join(root, p);
  if (!fp.startsWith(root) || !fs.existsSync(fp)) { res.writeHead(404); res.end(); return; }
  res.writeHead(200, { 'Content-Type': types[path.extname(fp)] || 'text/plain' });
  res.end(fs.readFileSync(fp));
});

(async () => {
  await new Promise(r => server.listen(0, r));
  const port = server.address().port;
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/chromium',
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();
  await page.goto(`http://localhost:${port}/index.html`, { waitUntil: 'networkidle0' });

  async function run(label) {
    const r = await new AxePuppeteer(page).analyze();
    console.log(`--- ${label} ---  violations=${r.violations.length}`);
    for (const v of r.violations) {
      console.log(`[${v.impact}] ${v.id}: ${v.help}`);
      v.nodes.forEach(n => {
        console.log('   target:', n.target.join(' '));
        console.log('   ', (n.failureSummary||'').replace(/\n/g, '\n    '));
      });
    }
    return r.violations.length;
  }

  let total = 0;
  total += await run('Closed');

  await page.click('.trigger');
  await new Promise(r => setTimeout(r, 300));
  total += await run('Open');

  await browser.close();
  server.close();
  process.exit(total ? 1 : 0);
})();
